package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.ReservationService; import com.agencytrip.agencytripapi.domain.model.Reservation; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@Tag(name="Reservas") @RestController @RequestMapping("/api/Reservas") public class ReservationController {private final ReservationService s;public ReservationController(ReservationService s){this.s=s;}@Operation(summary="Consultar reservas",description="El cliente obtiene sus reservas; los demás roles consultan todas.",security=@SecurityRequirement(name="bearerAuth"))@GetMapping public Object list(@AuthenticationPrincipal Jwt jwt){return (role(jwt).equals("CLIENTE")?s.byUser(id(jwt)):s.all()).stream().map(ApiResponses::reservation).toList();}@Operation(summary="Crear reserva",description="Valida cupos disponibles, calcula el total y descuenta cupos.",security=@SecurityRequirement(name="bearerAuth"))@PostMapping public Object create(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody Requests.Reservation r){Reservation x=s.create(id(jwt),r);return Map.of("mensaje","Reserva creada correctamente.","reserva",ApiResponses.reservation(x));}@Operation(summary="Cambiar estado de reserva",description="Solo ADMINISTRADOR. Al cancelar, devuelve los cupos del paquete.",security=@SecurityRequirement(name="bearerAuth"))@PutMapping("/{id}/estado")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object status(@PathVariable int id,@Valid@RequestBody Requests.ReservationStatus r){s.changeStatus(id,r);return Map.of("mensaje","Estado de la reserva actualizado correctamente.");}static int id(Jwt j){return ((Number)j.getClaim("userId")).intValue();}static String role(Jwt j){return j.getClaimAsStringList("roles").getFirst();}}
